entries[23807] = { ["name"] = "Bauplan: Adamantitzielfernrohr", ["text"] = "Benötigt Ingenieurskunst (335)\nBenutzen: Lehrt Euch die Herstellung eines Adamantitzielfernrohrs.\nVerkaufspreis:\nAdamantitzielfernrohr\nBenötigt Stufe 55\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit zugefügten Schaden um 10 .\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden.\nVerkaufspreis:\nBenötigt Adamantitbarren (8), Golddraenit (2)" }
