entries[23809] = { ["name"] = "Bauplan: Geeichtes Eterniumzielfernrohr", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (375)\nBenutzen: Lehrt Euch die Herstellung eines geeichten Eterniumzielfernrohrs.\nVerkaufspreis:\nGeeichtes Eterniumzielfernrohr\nBenötigt Stufe 60\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den kritischen Trefferwert um 28 .\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden.\nVerkaufspreis:\nBenötigt Gehärtetes Adamantitrohr (2), Teufelsstahlstabilisator (6), Stern der Elune (2)" }
entries[23810] = { ["name"] = "Bauplan: Krachbummroboter", ["text"] = "Benötigt Ingenieurskunst (325)\nBenutzen: Lehrt Euch die Herstellung eines Krachbummroboters.\nVerkaufspreis:\nKrachbummroboter\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Rechtsklicken, um einen robotischen Begleiter zu beschwören, der gegen andere Roboter kämpfen wird. (3 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Adamantitrahmen , Teufelseisengehäuse (2), Goldkraftkern , Eine Handvoll Teufelseisenbolzen (2)" }
entries[23811] = { ["name"] = "Bauplan: Weißes Rauchsignal", ["text"] = "Benötigt Ingenieurskunst (335)\nBenutzen: Lehrt Euch die Herstellung eines weißen Rauchsignals.\nVerkaufspreis:\nWeißes Rauchsignal\nBenutzen: Wirft ein weißes Rauchsignal in ein bestimmtes Gebiet. Hält 5 Min. lang an. (5 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Elementarsprengpulver , Netherstoff" }
entries[23812] = { ["name"] = "Bauplan: Rotes Rauchsignal", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (335)\nBenutzen: Lehrt Euch die Herstellung eines roten Rauchsignals.\nVerkaufspreis:\nRotes Rauchsignal\nBenutzen: Wirft ein rotes Rauchsignal in ein bestimmtes Gebiet. Hält 5 Min. lang an. (5 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Elementarsprengpulver , Netherstoff , Roter Farbstoff" }
entries[23813] = { ["name"] = "Bauplan: Blaues Rauchsignal", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (335)\nBenutzen: Lehrt Euch die Herstellung eines blauen Rauchsignals.\nVerkaufspreis:\nBlaues Rauchsignal\nBenutzen: Wirft ein blaues Rauchsignal in ein bestimmtes Gebiet. Hält 5 Min. lang an. (5 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Elementarsprengpulver , Netherstoff , Blauer Farbstoff" }
entries[23814] = { ["name"] = "Bauplan: Grünes Rauchsignal", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (335)\nBenötigt Expedition des Cenarius\n- Freundlich\nBenutzen: Lehrt Euch die Herstellung eines grünen Rauchsignals.\nVerkaufspreis:\nGrünes Rauchsignal\nBenutzen: Wirft ein grünes Rauchsignal in ein bestimmtes Gebiet. Hält 5 Min. lang an. (5 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Elementarsprengpulver , Netherstoff , Grüner Farbstoff" }
entries[23815] = { ["name"] = "Ruinierter Bauplan", ["text"] = "\"Dieser Bauplan wurde von den Elementen zerstört.\"\nVerkaufspreis:" }
entries[23816] = { ["name"] = "Bauplan: Werkzeugkasten aus Teufelseisen", ["text"] = "Benötigt Ingenieurskunst (325)\nBenutzen: Lehrt Euch die Herstellung eines Werkzeugkastens aus Teufelseisen.\nVerkaufspreis:\nWerkzeugkasten aus Teufelseisen\nWird beim Anlegen gebunden\n24 Platz Ingenieurstasche\nVerkaufspreis:\nBenötigt Teufelseisengehäuse , Teufelseisenbarren (5), Eine Handvoll Teufelseisenbolzen (2)" }
entries[23817] = { ["name"] = "Bauplan: Werkzeugkasten aus Titan", ["text"] = "Benötigt Ingenieurskunst (405)\nBenutzen: Lehrt Euch die Herstellung eines Werkzeugkastens aus Titan.\nVerkaufspreis:\nWerkzeugkasten aus Titan\nWird beim Anlegen gebunden\n32 Platz Ingenieurstasche\n\"Unterteilt in kleine Fächer, die sich perfekt für die Aufbewahrung von Ingenieursbedarf eignen.\"\nVerkaufspreis:\nBenötigt Saronitbarren (8), Titanbarren (8), Eine Handvoll Kobaltbolzen (4)" }
entries[23818] = { ["name"] = "Übersetzungsfibel der Tannenruhfeste", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Lehrt Euch, die Symbole der Furbolgs der Tannenruhfeste besser zu verstehen.\n\"Die Fibel enthält Übersetzungen für die Grundsymbole aus der Furbolgsprache.\"" }
entries[23819] = { ["name"] = "Elementare Zephyriumladung", ["text"] = "Benötigt Ingenieurskunst (350)\nBenutzen: Sprengt bis auf die stärksten alle verschlossenen Türen und Truhen auf.\nVerkaufspreis:" }
entries[23820] = { ["name"] = "Kleintiervergrößerer", ["text"] = "Benötigt Ingenieurskunst (325)\nBenutzen: Vergrößert ein Kleintier auf das Doppelte seiner normalen Größe. (15 Sek. Abklingzeit)\n\"Die Anwendungsmöglichkeiten für dieses Gerät sind nahezu unbegrenzt.\"\nVerkaufspreis:" }
entries[23821] = { ["name"] = "Schockdrosselnder Partikelextraktor", ["text"] = "Einzigartig\nBenötigt Ingenieurskunst (305)\nBenutzen: Extrahiert Gas aus einer in der Nähe befindlichen Gaswolke.\nZeigt die Position aller nahen Gaswolken auf der Minikarte an, solang sich der Partikelextraktor in Eurem Inventar befindet.\nVerkaufspreis:" }
entries[23822] = { ["name"] = "Heiltrankeinspritzung", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 2000 Gesundheit wieder her. Erhöhter Effekt für Ingenieure! (1 Min Abklingzeit)\n20 Aufladungen\n\"Heutzutage wird so etwas nicht mehr hergestellt...\"\nVerkaufspreis:" }
entries[23823] = { ["name"] = "Manatrankeinspritzung", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 2400 Mana wieder her. Erhöhter Effekt für Ingenieure! (1 Min Abklingzeit)\n20 Aufladungen\n\"Heutzutage wird so etwas nicht mehr hergestellt...\"\nVerkaufspreis:" }
entries[23824] = { ["name"] = "Raketenstiefel Xtrem", ["text"] = "Wird beim Anlegen gebunden\nFüße Leder\n350 Rüstung\n+40 Beweglichkeit\nHaltbarkeit 65 / 65\nBenötigt Ingenieurskunst (330)\nBenutzen: Die Raketenstiefel aktivieren, um einen gewaltigen Geschwindigkeitsschub zu erhalten. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[23825] = { ["name"] = "Gürtel der fast perfekten Unverwundbarkeit", ["text"] = "Wird beim Anlegen gebunden\nTaille Stoff\n201 Rüstung\n+21 Ausdauer\n43 Rüstung\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (350)\nBenutzen: Schützt Euch mit einem Energieschild, das 8 Sek. lang 4000 Schaden aufhält. (5 Min Abklingzeit)\n\"Der Schutz ist nicht immer wirksam. In SELTENEN Fällen kann der Träger zusätzlichen Schaden erleiden.\"\nVerkaufspreis:" }
entries[23826] = { ["name"] = "Die Größere", ["text"] = "Benötigt Ingenieurskunst (325)\nBenutzen: Fügt Zielen in einem Umkreis von 10 Metern 801 Feuerschaden zu und macht sie 5 Sek. lang handlungsunfähig. Jeglicher Schaden wird den Effekt abbrechen. Unzuverlässig gegen Ziele über Stufe 80. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[23827] = { ["name"] = "Super Pioniersprengladung", ["text"] = "Benötigt Ingenieurskunst (340)\nBenutzen: Explodiert bei Zündung, verursacht 1201 Feuerschaden an allen in der Nähe befindlichen feindlichen Einheiten und an Euch 674 Schaden. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[23828] = { ["name"] = "Gnomische Machtschutzbrille", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n279 Rüstung\n+32 Ausdauer\n+50 Intelligenz\nErhöht Eure kritische Trefferwertung um + 28.\nHaltbarkeit 100 / 100\nBenötigt Ingenieurskunst (375)\nBenötigt Gnomeningenieur\nVerkaufspreis:" }
entries[23829] = { ["name"] = "Gnomische Kampfschutzbrille", ["text"] = "Wird beim Aufheben gebunden\nKopf Leder\n391 Rüstung\n+50 Beweglichkeit\n+21 Ausdauer\nErhöht Eure kritische Trefferwertung um + 28.\nHaltbarkeit 100 / 100\nBenötigt Ingenieurskunst (375)\nBenötigt Gnomeningenieur\nVerkaufspreis:" }
entries[23830] = { ["name"] = "Kloppers Ausrüstung", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Ausrüstung scheint in Ordnung zu sein.\"" }
entries[23831] = { ["name"] = "Goblindampfpanzersteuerung", ["text"] = "Benutzen: Die Kontrolle über einen Dampfpanzer übernehmen.\n50 Aufladungen\nVerkaufspreis:" }
entries[23832] = { ["name"] = "Gnomische Dampfpanzersteuerung", ["text"] = "Benutzen: Die Kontrolle über einen Dampfpanzer übernehmen.\n50 Aufladungen\nVerkaufspreis:" }
entries[23833] = { ["name"] = "Kunstloses Murlocmesser", ["text"] = "Questgegenstand\n\"Eine grob behauene Steinklinge an einem langen Stab mit einer Sehne.\"" }
entries[23834] = { ["name"] = "Kunstloser Murlocgötze", ["text"] = "Questgegenstand\n\"Ein grob geschnitzter Götze, der keine erkennbare Figur darstellt.\"" }
entries[23835] = { ["name"] = "Gnomischer Geflügelisierer", ["text"] = "Wird beim Anlegen gebunden\nSchmuck\n+45 Ausdauer\nBenötigt Ingenieurskunst (340)\nBenötigt Gnomeningenieur\nBenutzen: Verwandelt den Gegner 15 Sek. lang in ein Huhn. Das heißt, falls die Transmogrifikationspolarität nicht verwechselt wurde... (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[23836] = { ["name"] = "Goblinraketenwerfer", ["text"] = "Wird beim Anlegen gebunden\nSchmuck\n+45 Ausdauer\nBenötigt Ingenieurskunst (350)\nBenötigt Gobliningenieur\nBenutzen: Feuert eine mächtige Rakete auf den Gegner, die 1500 Schaden verursacht und ihn 3 Sek. lang betäubt. Das Ding hat aber einen ziemlichen Rückstoß... (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[23837] = { ["name"] = "Verwitterte Schatzkarte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 13\n\"Das Pergament ist vergilbt, verblichen und voller Löcher, dennoch ist das Meiste noch lesbar.\"" }
entries[23838] = { ["name"] = "Verzauberter Helm des Vorarbeiters", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n279 Rüstung\n+70 Ausdauer\n+31 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Ingenieurskunst (350)\nBenötigt Gobliningenieur\nAnlegen: +10% Betäubungswiderstand.\nVerkaufspreis:" }
entries[23839] = { ["name"] = "Verstärkter Helm des Vorarbeiters", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n596 Rüstung\n+31 Beweglichkeit\n+70 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Ingenieurskunst (350)\nBenötigt Gobliningenieur\nAnlegen: Erhöht Eure Chance, Betäubungs- und Desorientierungseffekten zu widerstehen, um 10%.\nVerkaufspreis:" }
entries[23840] = { ["name"] = "Tragbarer Briefkasten", ["text"] = "Benötigt Ingenieurskunst (335)\nBenutzen: Entfaltet einen tragbaren Briefkasten, mit dem man Briefe schicken und empfangen kann. Seine Energie reicht 5 Min. lang.\nVerkaufspreis:" }
entries[23841] = { ["name"] = "Gnomisches Flammengeschütz", ["text"] = "Benötigt Ingenieurskunst (325)\nBenutzen: Errichtet schnell ein gnomisches Flammengeschütz zu Euren Füßen, das automatisch angreifen wird. Meistens Gegner. Das Geschütz fällt nach 45 Sek. in sich zusammen. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[23843] = { ["name"] = "Luftwirbel", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Teil von Susurrus, der auf irgendeine Weise an Eure Hand gebunden bleibt.\"" }
entries[23844] = { ["name"] = "Nolkais Laterne", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+3 Intelligenz\nVerkaufspreis:" }
entries[23845] = { ["name"] = "Felshetzerbalg", ["text"] = "Questgegenstand" }
entries[23846] = { ["name"] = "Nolkais Kasten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n<Zum Öffnen rechtsklicken>" }
entries[23847] = { ["name"] = "Nolkais Band", ["text"] = "\"Auf der Innenseite des Bands befindet sich eine Inschrift: Ein Erinnerungsstück von mir für meine Liebe. Möge Elune über meinen geliebten Nolkai wachen.\"" }
entries[23848] = { ["name"] = "Nethergarde Bitter", ["text"] = "Benötigt Stufe 30\nBenutzen: Ein extrem starkes alkoholisches Getränk.\nVerkaufspreis:" }
entries[23849] = { ["name"] = "Tannenruhgetreide", ["text"] = "Questgegenstand" }
entries[23850] = { ["name"] = "Gurfs Würde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 7\n\"Ein kleines Stück weißes Fell, das Gurf von der Tannenruhfeste gehört.\"" }
entries[23851] = { ["name"] = "Zerfleddertes Tagebuch", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Einband des Tagebuchs ist zerfleddert und die Seiten sind vergilbt; nur zwei der Einträge sind noch lesbar.\"" }
entries[23852] = { ["name"] = "Nolkais Tasche", ["text"] = "Wird beim Aufheben gebunden\n8 Platz Behälter\n\"Die Tasche war zwar einige Zeit in der Erde vergraben, der Zustand scheint jedoch fast wie neu.\"\nVerkaufspreis:" }
entries[23853] = { ["name"] = "Letter to <Name>" }
entries[23854] = { ["name"] = "Schattenzwirnstoff", ["text"] = "Verkaufspreis:" }
entries[23855] = { ["name"] = "Zauberfeuerstoff", ["text"] = "Verkaufspreis:" }
entries[23857] = { ["name"] = "Vermächtnis des Bergkönigs", ["text"] = "Karazhan\nEinzigartig\nBenutzen: Bricht das Siegel des Buches und gewährt Euch eine Chance, Eure Rüstung und Euren Magiewiderstand zu erhöhen, wenn Ihr im Gefecht getroffen werdet. (Procchance: 3%)\n\"Die Essenz dieses Buchs ist an Karazhan gebunden.\"" }
entries[23858] = { ["name"] = "Angesengte Seite", ["text"] = "\"Nachdem das Siegel von 'Vermächtnis des Bergkönigs' gebrochen wurde, verbleibt noch diese Seite.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[23859] = { ["name"] = "Glyphe vom Monument der Nazzivus", ["text"] = "Questgegenstand\nEinzigartig\n\"Finster aussehende Kreaturen in Begleitung einiger humanoider Gestalten bilden zusammen eine Art Erzählung.\"" }
entries[23860] = { ["name"] = "Kurkens Balg", ["text"] = "Questgegenstand\nEinzigartig" }
entries[23861] = { ["name"] = "Abschriftenset", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Erschafft einen Abdruck des Monuments der Satyrn von Nazzivus.\n\"Ein tragbares Abschriftenset zum Anfertigen einfacher Zeichnungen und Abpausbilder.\"" }
entries[23862] = { ["name"] = "Erlösung des Gefallenen", ["text"] = "Karazhan\nEinzigartig\nBenutzen: Bricht das Siegel des Buches und gewährt Euren Heilzaubern eine Chance, einen geisterhaften Verbündeten zu beschwören. (Procchance: 3%)\n\"Die Essenz dieses Buchs ist an Karazhan gebunden.\"" }
entries[23863] = { ["name"] = "Verderbter Kristall", ["text"] = "Questgegenstand\n\"Der Kristall pulsiert in einem aggressiven Rot. Man kann kaum glauben, dass dies einmal ein Teil der Exodar war.\"" }
entries[23864] = { ["name"] = "Qual des Worgen", ["text"] = "Karazhan\nEinzigartig\nBenutzen: Bricht das Siegel des Buches und gewährt Euch eine Chance, bei Nahkampf- und Distanzangriffen zusätzlichen Schattenschaden zu verursachen.\n\"Die Essenz dieses Buchs ist an Karazhan gebunden.\"" }
entries[23865] = { ["name"] = "Zorn der Titanen", ["text"] = "Karazhan\nEinzigartig\nBenutzen: Bricht das Siegel des Buches und gewährt Euren offensiven Zaubern eine Chance, zusätzlichen Schaden zuzufügen. (Procchance: 3%, 30s Abklingzeit)\n\"Die Essenz dieses Buchs ist an Karazhan gebunden.\"" }
entries[23866] = { ["name"] = "Angesengte Seite", ["text"] = "\"Nachdem das Siegel von 'Erlösung des Gefallenen' gebrochen wurde, verbleibt noch diese Seite.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[23867] = { ["name"] = "Angesengte Seite", ["text"] = "\"Nachdem das Siegel von 'Zorn der Titanen' gebrochen wurde, verbleibt noch diese Seite.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[23868] = { ["name"] = "Angesengte Seite", ["text"] = "\"Nachdem das Siegel von 'Qual des Worgen' gebrochen wurde, verbleibt noch diese Seite.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[23869] = { ["name"] = "Kristallisierte Rinde", ["text"] = "Questgegenstand\n\"Splitter von roten Kristallen haben sich in der Rinde festgesetzt und ersetzen teilweise das Holz.\"" }
entries[23870] = { ["name"] = "Roter Kristallanhänger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 9\n\"Ein Schmuckstück, das aus einem Kristallsplitter und einer gerollten Seetangkordel hergestellt wurde.\"" }
entries[23871] = { ["name"] = "Trank der Wasseratmung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (3)\nBenötigt Stufe 8\nBenutzen: Der Anwender kann 30 Min. lang unter Wasser atmen. (3 Sek. Abklingzeit)" }
entries[23872] = { ["name"] = "Blauer Ranzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[23873] = { ["name"] = "Galaens Amulett", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein kleiner, mit Juwelen besetzter Anhänger ist am Ende einer dünnen Kette befestigt.\"" }
entries[23874] = { ["name"] = "Bauplan: Elementare Zephyriumladung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (350)\nBenötigt Das Konsortium\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung einer elementaren Zephyriumladung.\nVerkaufspreis:\nElementare Zephyriumladung\nBenötigt Ingenieurskunst (350)\nBenutzen: Sprengt bis auf die stärksten alle verschlossenen Türen und Truhen auf.\nVerkaufspreis:\nBenötigt Elementarsprengpulver (2), Teufelseisengehäuse , Eine Handvoll Teufelseisenbolzen" }
entries[23875] = { ["name"] = "Kristallspitzhacke", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Entnimmt eine Probe des Kristalls zwischen den Trümmern des Absturzes." }
entries[23876] = { ["name"] = "Kristallspitzhacke", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Entnimmt einen Splitter eines Kristalls, der von den Blutelfen benutzt wird." }
entries[23877] = { ["name"] = "Kristallspitzhacke", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Entnimmt einen Splitter eines Kristalls in der Nazzuviussiedlung Axxarien." }
entries[23878] = { ["name"] = "Kristallprobe der Absturzstelle", ["text"] = "Einzigartig\n\"Ein Kristallbruchstück von den Trümmern der Exodar.\"" }
entries[23879] = { ["name"] = "Veränderte Kristallprobe", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser Kristallsplitter war einst ein Teil der Exodar, wurde aber von den Blutelfen verändert.\"" }
entries[23880] = { ["name"] = "Axxarienkristallprobe", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine Probe der Kristalle aus den Siedlungen der Satyrn.\"" }
entries[23881] = { ["name"] = "Gargolmars Hand", ["text"] = "Questgegenstand\nEinzigartig\n\"Trägt das Zeichen der Zerschmetterten Hand.\"" }
entries[23882] = { ["name"] = "Bauplan: Kleintiervergrößerer", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (325)\nBenutzen: Lehrt Euch die Herstellung eines Kleintiervergrößerers.\nVerkaufspreis:\nKleintiervergrößerer\nBenötigt Ingenieurskunst (325)\nBenutzen: Vergrößert ein Kleintier auf das Doppelte seiner normalen Größe. (15 Sek. Abklingzeit)\n\"Die Anwendungsmöglichkeiten für dieses Gerät sind nahezu unbegrenzt.\"\nVerkaufspreis:\nBenötigt Adamantitrahmen , Eine Handvoll Teufelseisenbolzen (2), Goldkraftkern" }
entries[23883] = { ["name"] = "Bauplan: Heiltrankeinspritzung", ["text"] = "Benötigt Ingenieurskunst (330)\nBenutzen: Lehrt Euch die Herstellung einer Heiltrankeinspritzung.\nVerkaufspreis:\nHeiltrankeinspritzung\nBenötigt Stufe 55\nBenutzen: Stellt 2000 Gesundheit wieder her. Erhöhter Effekt für Ingenieure! (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Teufelseisengehäuse , Eine Handvoll Teufelseisenbolzen , Knotenhautleder (2), Erstklassiger Heiltrank (20)" }
entries[23884] = { ["name"] = "Bauplan: Manatrankeinspritzung", ["text"] = "Benötigt Ingenieurskunst (345)\nBenutzen: Lehrt Euch die Herstellung einer Manatrankeinspritzung.\nVerkaufspreis:\nManatrankeinspritzung\nBenötigt Stufe 55\nBenutzen: Stellt 2400 Mana wieder her. Erhöhter Effekt für Ingenieure! (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Teufelseisengehäuse , Eine Handvoll Teufelseisenbolzen , Knotenhautleder (2), Erstklassiger Manatrank (20)" }
entries[23885] = { ["name"] = "Bauplan: Tragbarer Briefkasten", ["text"] = "Benötigt Ingenieurskunst (335)\nBenutzen: Lehrt Euch die Herstellung eines tragbaren Briefkastens.\nVerkaufspreis:\nTragbarer Briefkasten\nBenötigt Ingenieurskunst (335)\nBenutzen: Entfaltet einen tragbaren Briefkasten, mit dem man Briefe schicken und empfangen kann. Seine Energie reicht 5 Min. lang.\nVerkaufspreis:\nBenötigt Adamantitrahmen , Eine Handvoll Teufelseisenbolzen (2), Khoriumkraftkern , Verschmorte Verkabelung" }
entries[23886] = { ["name"] = "Omors Huf", ["text"] = "Questgegenstand\nEinzigartig\n\"Riecht nach Tod und Angst.\"" }
entries[23887] = { ["name"] = "Bauplan: Raketenstiefel Xtrem", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (355)\nBenutzen: Lehrt Euch die Herstellung von Raketenstiefeln Xtrem.\nVerkaufspreis:\nRaketenstiefel Xtrem\nWird beim Anlegen gebunden\nFüße Leder\n350 Rüstung\n+40 Beweglichkeit\nHaltbarkeit 65 / 65\nBenötigt Ingenieurskunst (330)\nBenutzen: Die Raketenstiefel aktivieren, um einen gewaltigen Geschwindigkeitsschub zu erhalten. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (8), Khoriumkraftkern (2), Gehärtetes Adamantitrohr (2), Teufelsstahlstabilisator (4)" }
entries[23888] = { ["name"] = "Bauplan: Schockdrosselnder Partikelextraktor", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (305)\nBenutzen: Lehrt Euch die Herstellung eines schockdrosselnden Partikelextraktors.\nVerkaufspreis:\nSchockdrosselnder Partikelextraktor\nEinzigartig\nBenötigt Ingenieurskunst (305)\nBenutzen: Extrahiert Gas aus einer in der Nähe befindlichen Gaswolke.\nZeigt die Position aller nahen Gaswolken auf der Minikarte an, solang sich der Partikelextraktor in Eurem Inventar befindet.\nVerkaufspreis:\nBenötigt Teufelseisengehäuse (2), Eine Handvoll Teufelseisenbolzen (2), Urleben (4), Empfindlicher Arkanitwandler" }
