entries[24000] = { ["name"] = "Formel: Armschiene - Überragende Heilung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (325)\nBenötigt Thrallmar\n- Freundlich\nBenutzen: Lehrt Euch15 Armschienen dauerhaft zu verzaubern15 sodass die Zaubermacht um 15 erhöht wird. Erfordert einen Gegenstand der Stufe 15 oder höher.\nArmschienen dauerhaft verzaubern, sodass die Zaubermacht um 15 erhöht wird.\nVerkaufspreis:" }
entries[24001] = { ["name"] = "Rezept: Elixier der erheblichen Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(330)\nBenötigt Thrallmar\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Beweglichkeit.\nVerkaufspreis:\nElixier der erheblichen Beweglichkeit\nBenötigt Stufe 55\nBenutzen: Erhöht 1 Stunde lang die Beweglichkeit um 30 und den kritischen Trefferwert um 12 . Kampfelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Terozapfen , Teufelsgras (2), Kristallphiole" }
entries[24002] = { ["name"] = "Pläne: Teufelsstahlschildstachel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (360)\nBenötigt Thrallmar\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Teufelsstahlschildstachels.\nVerkaufspreis:\nTeufelsstahlschildstachel\nBenutzen: Bringt einen Teufelsstahlstachel an Eurem Schild an, der bei jedem Blocken 26-38 Schaden verursacht.\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (4), Urfeuer (4), Urerde (4)" }
entries[24003] = { ["name"] = "Formel: Brust - Außergewöhnliche Werte", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (345)\nBenötigt Thrallmar\n- Respektvoll\nBenutzen: Lehrt Euch6 Brustrüstungen dauerhaft zu verzaubern6 sodass alle Werte um 6 erhöht werden. Erfordert einen Gegenstand der Stufe 6 oder höher.\nEine Brustrüstung dauerhaft verzaubern, sodass alle Werte um 6 erhöht werden.\nVerkaufspreis:" }
