entries[24177] = { ["name"] = "Vorlage: Anhänger der Schattenneige", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelierskunst\n(360)\nBenötigt Die Aldor\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung eines Anhängers der Schattenneige.\nVerkaufspreis:\nAnhänger der Schattenneige\nWird beim Anlegen gebunden\nHals\n+18 Ausdauer\n+30 Schattenwiderstand\nBenötigt Stufe 70\nBenutzen: Absorbiert 900 bis 2700 Schattenschaden, den in der Nähe befindliche Gruppenmitglieder erleiden. Hält 5 Min. lang an. (1 Stunde Abklingzeit)\n10 Aufladungen\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (2), Urleben (6), Urschatten (4), Quecksilberadamantit" }
entries[24178] = { ["name"] = "Vorlage: Anhänger der Nullrune", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelierskunst\n(360)\nBenötigt Das Konsortium\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung eines Anhängers der Nullrune.\nVerkaufspreis:\nAnhänger der Nullrune\nWird beim Anlegen gebunden\nHals\n+18 Ausdauer\n+30 Arkanwiderstand\nBenötigt Stufe 70\nBenutzen: Absorbiert 900 bis 2700 Arkanschaden, den in der Nähe befindliche Gruppenmitglieder erleiden. Hält 5 Min. lang an. (1 Stunde Abklingzeit)\n10 Aufladungen\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (2), Urmana (8), Quecksilberadamantit" }
entries[24179] = { ["name"] = "Vorlage: Teufelsstahleber", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelierskunst\n(370)\nBenötigt Unteres Viertel\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung eines Teufelsstahlebers.\nVerkaufspreis:\nFigur - Teufelsstahleber\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 68 Angriffskraft.\nBenötigt Stufe 70\nBenötigt Juwelierskunst\n(370)\nBenutzen: Beschwört einen Teufelsstahleber, der 30 Sek. lang für Euch kämpft. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (8), Blutgranat (2), Urerde (4)" }
entries[24180] = { ["name"] = "Vorlage: Dämmersteinkrebs", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelierskunst\n(370)\nBenötigt Ehrenfeste\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung eines Dämmersteinkrebses.\nVerkaufspreis:\nFigur - Dämmersteinkrebs\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 32 Ausweichen\nBenötigt Stufe 70\nBenötigt Juwelierskunst\n(370)\nBenutzen: Erhöht das Ausweichen 20 Sek. lang um 153 . (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Khoriumbarren (4), Dämmerstein (2), Golddraenit (4)" }
entries[24181] = { ["name"] = "Vorlage: Lebendige Rubinschlange", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelierskunst\n(370)\nBenötigt Hüter der Zeit\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung einer lebendigen Rubinschlange.\nVerkaufspreis:\nFigur - Lebendige Rubinschlange\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+33 Ausdauer\n+23 Intelligenz\nBenötigt Stufe 70\nBenötigt Juwelierskunst\n(370)\nBenutzen: Erhöht die Zaubermacht 20 Sek. lang um 183 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (2), Lebendiger Rubin (2), Urfeuer (4)" }
entries[24182] = { ["name"] = "Vorlage: Talasiteule", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelierskunst\n(370)\nBenötigt Die Sha'tar\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung einer Talasiteule.\nVerkaufspreis:\nFigur - Talasiteule\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+36 Willenskraft\nBenötigt Stufe 70\nBenötigt Juwelierskunst\n(370)\nBenutzen: Stellt im Verlauf von 12 Sek. insgesamt 1100 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Eterniumbarren (2), Talasit (2), Urmana (4)" }
entries[24183] = { ["name"] = "Vorlage: Nachtaugenpanther", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelierskunst\n(370)\nBenötigt Expedition des Cenarius\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung eines Nachtaugenpanthers.\nVerkaufspreis:\nFigur - Nachtaugenpanther\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 54 Angriffskraft.\nBenötigt Stufe 70\nBenötigt Juwelierskunst\n(370)\nBenutzen: Erhöht die Angriffskraft 12 Sek. lang um 391 . (3 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Gehärteter Adamantitbarren (6), Nachtauge (2), Urschatten (2)" }
